export const meta = {
  name: 'swiftmandarin-deep-audit',
  description: 'Map every subsystem, hunt hidden bugs across dimensions, adversarially verify findings, and audit features/HIG',
  phases: [
    { title: 'Map & Find', detail: 'subsystem readers + cross-cutting bug finders' },
    { title: 'Verify', detail: 'adversarial verification of each candidate bug' },
    { title: 'Synthesize', detail: 'feature-gap and integration synthesis' },
  ],
}

const ROOT = '/Users/rogerlin/XCode-Projects/SwiftMandarinShortcuts'
const SRC = ROOT + '/SwiftMandarin'

const CONTEXT = `
App: SwiftMandarin — a multiplatform (iOS/macOS/visionOS 26.2, Swift 5 mode, single target, sandboxed) SwiftUI app for bilingual Mandarin↔English learning. Features: text translation (Apple Intelligence / Ollama / 8 cloud AI providers), photo OCR translation (Vision framework), workbook photo grading (vision AI), vocabulary book, flashcard learning, phrases, stats, live speech translation, App Intents/Shortcuts, full EN⇄中文 runtime language toggle (LocalizationManager Bundle override + .localizedSurface() modifier required on ALL sheet/popover content).
State pattern: @Observable @MainActor singletons (.shared) persisted as JSON in UserDefaults; injected via .environment but often reached as singletons.
API keys in Keychain (account "apikey.<provider.rawValue>"). Cloud calls via Services/CloudAIService.swift (OpenAI-compatible + Anthropic styles). Dispatch chokepoint: Services/AIWordExplanationService.swift.
Known-good baseline: both platforms build clean. Your job is to find what is still wrong or missing, not to re-litigate the architecture.`

const ISSUE_SCHEMA = {
  type: 'object',
  properties: {
    summary: { type: 'string', description: '2-4 sentence map of what this subsystem/dimension does and how it connects to the rest of the app' },
    issues: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          title: { type: 'string' },
          file: { type: 'string', description: 'path relative to repo root' },
          line: { type: 'number' },
          severity: { type: 'string', enum: ['critical', 'high', 'medium', 'low'] },
          confidence: { type: 'string', enum: ['certain', 'likely', 'possible'] },
          description: { type: 'string', description: 'what is wrong, the user-visible symptom, and evidence (quote the offending code)' },
          suggestedFix: { type: 'string' },
        },
        required: ['title', 'file', 'severity', 'confidence', 'description', 'suggestedFix'],
      },
    },
    featureIdeas: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          title: { type: 'string' },
          rationale: { type: 'string' },
          effort: { type: 'string', enum: ['small', 'medium', 'large'] },
        },
        required: ['title', 'rationale', 'effort'],
      },
    },
  },
  required: ['summary', 'issues', 'featureIdeas'],
}

const VERDICT_SCHEMA = {
  type: 'object',
  properties: {
    isReal: { type: 'boolean' },
    reasoning: { type: 'string', description: 'cite the exact code you read that proves or refutes the claim' },
    severity: { type: 'string', enum: ['critical', 'high', 'medium', 'low'] },
    fixApproach: { type: 'string', description: 'concrete fix, empty if not real' },
  },
  required: ['isReal', 'reasoning', 'severity', 'fixApproach'],
}

const finderPreamble = (scope) => `You are auditing the SwiftMandarin codebase at ${ROOT}.
${CONTEXT}

Your scope: ${scope}

Read EVERY file in your scope COMPLETELY (use Read; files are at most ~1400 lines). Then report:
1. A short map (summary) of the scope and its cross-connections.
2. Concrete issues: real bugs, logic errors, broken edge cases, dead code, inconsistencies, unlocalized strings, missing error handling, races. Be selective and evidence-based — max 10 issues, each with the offending code quoted in the description. Do NOT report style nits, hypothetical perf concerns, or "could be refactored" items. A finding must have a user-visible or correctness consequence.
3. Feature ideas: missing capabilities or integration gaps a user of THIS app would actually want (max 5, grounded in what the code already supports).
Severity: critical = data loss/crash; high = feature broken or wrong result; medium = degraded UX/edge-case failure; low = polish.`

const SUBSYSTEMS = [
  { key: 'app-shell', scope: `App shell & navigation: ${SRC}/SwiftMandarinApp.swift, ${SRC}/ContentView.swift, ${SRC}/Item.swift, ${SRC}/Models/AppRouteStore.swift, ${SRC}/Models/LocalizationManager.swift, ${SRC}/Models/AppPreferences.swift. Also run: plutil -p ${SRC.replace(/ /g, '\\ ')}/../SwiftMandarin.xcodeproj/project.pbxproj 2>/dev/null | head -5 || true — instead just Read ${ROOT}/SwiftMandarin.xcodeproj/project.pbxproj (skim build settings: INFOPLIST_KEY_*, entitlements, deploy targets) and ${SRC}/SwiftMandarin.entitlements.` },
  { key: 'models-data', scope: `Data models & persistence: ${SRC}/Models/TranslationHistory.swift, ${SRC}/Models/SavedTerm.swift, ${SRC}/Models/LearningCard.swift, ${SRC}/Models/LearningActivity.swift, ${SRC}/Models/GrammarPoint.swift, ${SRC}/Models/TranslationDirection.swift, ${SRC}/Models/TranslationState.swift, ${SRC}/Models/ScreenshotTranslationStore.swift. Focus: persistence integrity (UserDefaults JSON round-trips), Codable tolerance, ID stability, date math (streaks/SRS scheduling), duplicate handling.` },
  { key: 'services-ai', scope: `AI services: ${SRC}/Models/AIModelSettings.swift, ${SRC}/Services/CloudAIService.swift, ${SRC}/Services/AIWordExplanationService.swift, ${SRC}/Services/OllamaService.swift, ${SRC}/Services/KeychainHelper.swift, ${SRC}/Services/WordTranslationService.swift. Focus: request building per provider/apiStyle, JSON parsing tolerance, error propagation to UI, timeout/cancellation, Keychain correctness, model-list refresh, vision/multi-image paths.` },
  { key: 'services-text', scope: `Text/speech/OCR services: ${SRC}/Services/ChineseTextAnalyzer.swift, ${SRC}/Services/EnglishTextAnalyzer.swift, ${SRC}/Services/PinyinConverter.swift, ${SRC}/Services/PhotoTextRecognitionService.swift, ${SRC}/Services/ScreenshotStitchingService.swift, ${SRC}/Services/SpeechRecognitionService.swift, ${SRC}/Services/SpeechService.swift, ${SRC}/Services/ClipboardService.swift, ${SRC}/Services/VocabularyImportExportService.swift. Focus: language detection edge cases, tokenization, pinyin correctness, OCR language parameterization consistency across the 3 OCR paths, audio session lifecycle, import/export round-trip fidelity.` },
  { key: 'views-core', scope: `Core feature views: ${SRC}/Views/TranslateView.swift, ${SRC}/Views/PhotoTranslateView.swift, ${SRC}/Views/WorkbookGradingView.swift. Focus: state flow, task cancellation on dismiss, error surfacing, localization (.localizedSurface on every sheet/popover/fullScreenCover), platform conditionals (#if os), accessibility.` },
  { key: 'views-learning', scope: `Learning & library views: ${SRC}/Views/VocabularyView.swift, ${SRC}/Views/LearnView.swift, ${SRC}/Views/StatsView.swift, ${SRC}/Views/PhrasesView.swift, ${SRC}/Views/HistoryTabView.swift. Focus: SRS/flashcard logic, stats correctness (streaks, charts), list performance, swipe actions, localization of sheets, empty states.` },
  { key: 'views-settings-components', scope: `Settings & shared components: ${SRC}/Views/MoreView.swift, ${SRC}/Views/MacOSSettingsView.swift, ${SRC}/Views/Components/AIProviderConfigView.swift, ${SRC}/Views/Components/ProviderIcon.swift, ${SRC}/Views/Components/SingleLineFit.swift, ${SRC}/Views/Components/RubyTextView.swift, ${SRC}/Views/Components/EnglishRubyTextView.swift, ${SRC}/Views/Components/AIWordExplanationView.swift, ${SRC}/Views/Components/CameraScannerView.swift, ${SRC}/Views/Components/LiveSpeechTranslationView.swift, ${SRC}/Views/Components/TranslatedScreenshotOverlayView.swift. Focus: settings consistency between iOS and macOS surfaces, component correctness, camera/speech lifecycle, ruby text alignment.` },
  { key: 'intents', scope: `App Intents & Shortcuts: every file in ${SRC}/Intents/. Focus: intent parameter validation, @MainActor correctness, whether intents reuse the same services/stores as the UI (or have drifted copies), result dialogs localization, entity queries.` },
]

const DIMENSIONS = [
  { key: 'concurrency', prompt: `${finderPreamble('CROSS-CUTTING: Swift concurrency & lifecycle audit over the whole codebase.')} Grep for Task {, Task.detached, DispatchQueue, @MainActor, nonisolated, .task, onChange, Timer, NotificationCenter across ${SRC} and inspect each hit in context. Hunt: UI mutation off the main actor, tasks not cancelled when views disappear (retain cycles / stale writes), un-awaited detached work, audio/camera session leaks, AVAudioSession misconfiguration, double .shared init races.` },
  { key: 'localization', prompt: `${finderPreamble('CROSS-CUTTING: localization completeness audit.')} The app has a runtime EN⇄中文 toggle; every user-visible string must resolve through the catalog and every presented sheet/popover/fullScreenCover/alert content must apply .localizedSurface(). 1) Grep ${SRC} for: Text(", Label(", Button(", .navigationTitle, .alert, ContentUnavailableView, and verbatim String-typed text passed to views — find user-visible strings that bypass LocalizedStringKey (e.g. Text(someStringVariable) fed from a String literal, string interpolation that produces English-only output, hardcoded formatter output). 2) Grep for .sheet(, .popover(, .fullScreenCover( and verify each closure's root applies .localizedSurface(). 3) Check Localizable.xcstrings (it is huge — sample it with python3 json parsing via Bash: count keys, find entries missing zh-Hans or en translations, list them). Report concrete gaps only.` },
  { key: 'integration', prompt: `${finderPreamble('CROSS-CUTTING: integration & cohesion audit — places where features exist but are not wired together.')} Examples to investigate: Does photo OCR text offer the same word-tap/explanation affordances as TranslateView? Does workbook grading vocab reach the Learn flashcards? Is TranslationHistory written by ALL translation paths (text, photo, screenshot, live speech, intents)? Do App Intents and UI share stores? Does SavedTerm flow into LearningCard SRS automatically? Is the language toggle respected everywhere (speech voices, OCR defaults)? Does Stats count activity from every feature (grading, photo, speech) or only some? Map the actual data flow by reading the relevant files and report gaps a user would notice as "these features don't talk to each other".` },
  { key: 'hig-ui', prompt: `${finderPreamble("CROSS-CUTTING: Apple HIG / UI quality audit of all Views.")} Evaluate against macOS+iOS HIG: toolbar placement, navigation patterns (NavigationSplitView vs TabView usage), destructive-action confirmation, .searchable usage, keyboard shortcuts on macOS, focus management, empty states (ContentUnavailableView), loading states, error presentation (alerts vs inline), Dynamic Type resilience, accessibility labels on icon-only buttons, color/contrast, haptics, platform-idiomatic Settings. Report concrete, fixable violations with file:line, max 12, ranked by user impact. Also note quick HIG wins (e.g. missing .keyboardShortcut, missing accessibilityLabel on image buttons).` },
]

phase('Map & Find')
const allResults = await parallel([
  ...SUBSYSTEMS.map(s => () => agent(finderPreamble(s.scope), { label: `map:${s.key}`, phase: 'Map & Find', schema: ISSUE_SCHEMA, agentType: 'Explore' })),
  ...DIMENSIONS.map(d => () => agent(d.prompt, { label: `find:${d.key}`, phase: 'Map & Find', schema: ISSUE_SCHEMA, agentType: 'Explore' })),
])

const ok = allResults.filter(Boolean)
const maps = ok.map((r, i) => ({ scope: i < SUBSYSTEMS.length ? (SUBSYSTEMS[i] || {}).key : 'dim', summary: r.summary }))
const allIssues = ok.flatMap(r => r.issues || [])
const allIdeas = ok.flatMap(r => r.featureIdeas || [])

// dedup by file + normalized title prefix
const seen = new Map()
for (const iss of allIssues) {
  const k = (iss.file || '') + '|' + (iss.title || '').toLowerCase().replace(/[^a-z0-9]/g, '').slice(0, 32)
  if (!seen.has(k)) seen.set(k, iss)
}
const unique = Array.from(seen.values())
log(`${allIssues.length} raw findings → ${unique.length} unique; ${allIdeas.length} feature ideas`)

// Verify everything except 'low'+'possible' noise; cap at 45
const toVerify = unique
  .filter(i => !(i.severity === 'low' && i.confidence === 'possible'))
  .slice(0, 45)
const skipped = unique.filter(i => !toVerify.includes(i))
log(`Verifying ${toVerify.length} findings adversarially (${skipped.length} low-confidence carried unverified)`)

phase('Verify')
const verified = await parallel(toVerify.map(f => () =>
  agent(`You are an adversarial verifier for the SwiftMandarin codebase at ${ROOT}. ${CONTEXT}

A finder claims this bug exists. Your job is to REFUTE it if possible. Read the cited file (${f.file}${f.line ? ' around line ' + f.line : ''}) and any related files needed to trace the actual behavior. The claim:

TITLE: ${f.title}
SEVERITY CLAIMED: ${f.severity}
CLAIM: ${f.description}
SUGGESTED FIX: ${f.suggestedFix}

Rules: isReal=true ONLY if you traced the code and the user-visible consequence actually occurs. If the claim is technically true but has no user-visible/correctness consequence, isReal=false. If uncertain after reading, isReal=false. Quote the decisive code in your reasoning.`,
    { label: `verify:${(f.title || '').slice(0, 40)}`, phase: 'Verify', schema: VERDICT_SCHEMA, agentType: 'Explore' })
    .then(v => ({ ...f, verdict: v }))
))

const confirmed = verified.filter(Boolean).filter(x => x.verdict && x.verdict.isReal)
const refuted = verified.filter(Boolean).filter(x => x.verdict && !x.verdict.isReal)
log(`${confirmed.length} confirmed, ${refuted.length} refuted`)

phase('Synthesize')
const synthesis = await agent(`You are synthesizing an overhaul plan for SwiftMandarin at ${ROOT}. ${CONTEXT}

CONFIRMED BUGS (already adversarially verified — do not re-verify):
${JSON.stringify(confirmed.map(c => ({ title: c.title, file: c.file, line: c.line, severity: c.verdict.severity, fix: c.verdict.fixApproach })), null, 1)}

FEATURE IDEAS from 12 auditors:
${JSON.stringify(allIdeas, null, 1)}

SUBSYSTEM SUMMARIES:
${JSON.stringify(maps, null, 1)}

Produce a prioritized overhaul plan: (1) order the confirmed bugs into fix batches that touch related files together; (2) pick the 5-8 highest-value feature/integration enhancements that are SMALL-to-MEDIUM effort and grounded in existing code (cite which existing services/stores they reuse) — favor integration wins (features talking to each other) and HIG polish over brand-new subsystems; (3) flag anything risky. Return plain text, well organized.`,
  { label: 'synthesize', phase: 'Synthesize' })

return {
  confirmedBugs: confirmed.map(c => ({ title: c.title, file: c.file, line: c.line, severity: c.verdict.severity, description: c.description, fix: c.verdict.fixApproach })),
  refutedCount: refuted.length,
  unverifiedLowPriority: skipped.map(s => ({ title: s.title, file: s.file, severity: s.severity })),
  synthesis,
}

