57	        switch self {
58	        case .appleIntelligence: return "On-device AI powered by Apple's Foundation Models"
59	        case .ollama: return "Local AI models running via Ollama server"
60	        case .openAI: return "GPT models via the OpenAI API"
61	        case .anthropic: return "Claude models via the Anthropic API"
62	        case .deepseek: return "DeepSeek chat & reasoning models"
63	        case .doubao: return "ByteDance Doubao models via Volcengine Ark"
64	        case .qwen: return "Alibaba Qwen models via DashScope"
65	        case .kimi: return "Moonshot Kimi models"
66	        case .zhipu: return "Zhipu GLM models"
67	        case .minimax: return "MiniMax abab models"
68	        }
69	    }
70	
71	    /// SF Symbol fallback, used only if the brand asset is unavailable.
72	    var iconName: String {
73	        switch self {
74	        case .appleIntelligence: return "apple.logo"
75	        case .ollama: return "server.rack"
76	        case .openAI: return "sparkles"
77	        case .anthropic: return "a.circle"
78	        case .deepseek: return "magnifyingglass.circle"
79	        case .doubao: return "cloud"
80	        case .qwen: return "cloud.sun"
81	        case .kimi: return "moon.stars"
82	        case .zhipu: return "brain"
83	        case .minimax: return "bolt.horizontal.circle"
84	        }
85	    }
86	
87	    /// Name of the brand image in `Assets.xcassets` (vector SVG). Render via
88	    /// the shared `ProviderIcon` view, which falls back to `iconName` when the
89	    /// asset is missing.
90	    var brandAssetName: String { "brand-\(rawValue)" }
91	
92	    /// Whether the brand asset is a single-color glyph that should be tinted to
93	    /// the surrounding foreground color (so it adapts to light/dark mode).
94	    /// Full-color brand marks render in their original colors instead.
95	    var brandAssetIsMonochrome: Bool {
96	        switch self {
97	        case .appleIntelligence, .openAI, .ollama: return true
98	        default: return false
99	        }
100	    }
101	
102	    /// Whether this provider is a remote cloud API requiring an API key.
103	    var isCloud: Bool {
104	        switch self {
105	        case .appleIntelligence, .ollama: return false
106	        default: return true
107	        }
108	    }
