119	    /// supported. Providers without it still receive the JSON schema in the
120	    /// prompt and are parsed with tolerant extraction.
121	    var supportsJSONResponseFormat: Bool {
122	        switch self {
123	        case .openAI, .deepseek, .kimi, .qwen: return true
124	        case .anthropic, .doubao, .zhipu, .minimax, .appleIntelligence, .ollama: return false
125	        }
126	    }
127	
128	    // MARK: Cloud REST metadata (only meaningful when `isCloud`)
129	
130	    var apiStyle: AIProviderAPIStyle {
131	        switch self {
132	        case .anthropic: return .anthropic
133	        default: return .openAICompatible
134	        }
135	    }
136	
137	    /// Default base URL (without a trailing slash). Paths below are appended.
138	    var defaultBaseURL: String {
139	        switch self {
140	        case .openAI: return "https://api.openai.com/v1"
141	        case .anthropic: return "https://api.anthropic.com"
142	        case .deepseek: return "https://api.deepseek.com"
143	        case .doubao: return "https://ark.cn-beijing.volces.com/api/v3"
144	        // International (Singapore) endpoint — works without a workspace ID.
145	        // China users can override with https://dashscope.aliyuncs.com/compatible-mode/v1
146	        case .qwen: return "https://dashscope-intl.aliyuncs.com/compatible-mode/v1"
147	        case .kimi: return "https://api.moonshot.cn/v1"
148	        case .zhipu: return "https://open.bigmodel.cn/api/paas/v4"
149	        case .minimax: return "https://api.minimax.chat/v1"
150	        case .appleIntelligence, .ollama: return ""
151	        }
152	    }
