154	    /// Chat-completion path appended to the base URL.
155	    var chatPath: String {
156	        switch self {
157	        case .anthropic: return "/v1/messages"
158	        case .minimax: return "/text/chatcompletion_v2"
159	        default: return "/chat/completions"
160	        }
161	    }
162	
163	    /// Model-list path appended to the base URL, or `nil` when the provider
164	    /// has no standard listing endpoint (defaults are used instead).
165	    var modelsPath: String? {
166	        switch self {
167	        case .anthropic: return "/v1/models"
168	        case .openAI, .deepseek, .qwen, .kimi, .doubao: return "/models"
169	        case .zhipu, .minimax: return nil
170	        case .appleIntelligence, .ollama: return nil
171	        }
172	    }
