174	    /// Curated fallback model IDs shown when live listing is unavailable.
175	    /// These are only a starting hint — use "Refresh Models" to pull the
176	    /// provider's current list from its API.
177	    var defaultModels: [String] {
178	        switch self {
179	        case .openAI:
180	            return ["gpt-4o", "gpt-4.1", "gpt-4.1-mini", "o4-mini", "o3", "gpt-4o-mini"]
