186	            // Ark model IDs use dashes + a date suffix (NOT dots), and must be
187	            // activated in the Ark Console (or use an inference endpoint ID, ep-…).
188	            return ["doubao-seed-1-6-250615", "doubao-1-5-pro-32k-250115", "doubao-1-5-vision-pro-32k-250115", "doubao-seed-1-6-flash-250828", "doubao-1-5-lite-32k-250115"]
189	        case .qwen:
190	            return ["qwen-plus", "qwen-max", "qwen-turbo", "qwen-vl-max", "qwen-vl-plus", "qwen-max-latest"]
191	        case .kimi:
192	            return ["kimi-latest", "kimi-k2-0711-preview", "kimi-k2-turbo-preview", "moonshot-v1-128k", "moonshot-v1-auto", "moonshot-v1-128k-vision-preview"]
193	        case .zhipu:
194	            return ["glm-4.6", "glm-4.5", "glm-4-plus", "glm-4.5v", "glm-4v-plus", "glm-4-flash"]
195	        case .minimax:
196	            return ["MiniMax-Text-01", "MiniMax-M1", "abab6.5s-chat"]
197	        case .appleIntelligence, .ollama:
198	            return []
199	        }
200	    }
201	
202	    /// A known vision-capable model id for this provider, used when an image
203	    /// task (grading, photo cleanup) needs vision but the user's selected model
204	    /// is text-only.
205	    var defaultVisionModel: String? {
206	        switch self {
207	        case .openAI: return "gpt-4o"
208	        case .anthropic: return "claude-sonnet-4-5"
209	        case .qwen: return "qwen-vl-max"
210	        case .doubao: return "doubao-1-5-vision-pro-32k-250115"
