214	        }
215	    }
216	
217	    /// Keychain account name for this provider's API key.
218	    var keychainAccount: String { "apikey.\(rawValue)" }
219	
220	    /// URL to obtain an API key, for the settings help link.
221	    var apiKeyURL: String? {
222	        switch self {
223	        case .openAI: return "https://platform.openai.com/api-keys"
224	        case .anthropic: return "https://console.anthropic.com/settings/keys"
