227	        case .qwen: return "https://dashscope.console.aliyun.com/apiKey"
228	        case .kimi: return "https://platform.moonshot.cn/console/api-keys"
229	        case .zhipu: return "https://open.bigmodel.cn/usercenter/apikeys"
230	        case .minimax: return "https://platform.minimaxi.com/user-center/basic-information/interface-key"
231	        case .appleIntelligence, .ollama: return nil
232	        }
