236	// MARK: - AI Model Settings
237	
238	/// Observable settings for AI model configuration.
239	@Observable
240	@MainActor
241	final class AIModelSettings {
242	
243	    static let shared = AIModelSettings()
244	
245	    // MARK: - UserDefaults Keys
246	
247	    private enum Keys {
248	        static let provider = "ai_provider"
249	        static let ollamaModel = "ollama_model"
250	        static let ollamaHost = "ollama_host"
251	        static let enableThinking = "ollama_enable_thinking"
252	        static let contextLength = "ollama_context_length"
253	        static let cloudModels = "cloud_model_selections"   // [providerRaw: modelID]
254	        static let cloudBaseURLs = "cloud_base_overrides"   // [providerRaw: baseURL]
255	        static let cloudAPIStyles = "cloud_api_style_overrides" // [providerRaw: "openai"|"anthropic"]
256	        static let aiPhotoCleanup = "ai_photo_cleanup_enabled"
257	    }
258	
259	    // MARK: - Properties
260	
261	    /// The currently selected AI provider.
262	    var provider: AIProvider {
263	        didSet { UserDefaults.standard.set(provider.rawValue, forKey: Keys.provider) }
264	    }
265	
266	    /// The selected Ollama model name.
267	    var ollamaModel: String {
268	        didSet { UserDefaults.standard.set(ollamaModel, forKey: Keys.ollamaModel) }
269	    }
270	
271	    /// The Ollama server host URL.
272	    var ollamaHost: String {
273	        didSet {
274	            UserDefaults.standard.set(ollamaHost, forKey: Keys.ollamaHost)
275	            updateOllamaServiceHost()
276	        }
277	    }
278	
279	    /// Whether to enable thinking/reasoning mode for Ollama models.
280	    var enableThinking: Bool {
281	        didSet { UserDefaults.standard.set(enableThinking, forKey: Keys.enableThinking) }
282	    }
283	
284	    /// Context length for Ollama models (in tokens).
285	    var contextLength: Int {
286	        didSet { UserDefaults.standard.set(contextLength, forKey: Keys.contextLength) }
287	    }
288	
289	    /// When enabled, uploaded photos are passed through the selected AI
290	    /// provider for OCR cleanup/structuring before downstream processing.
291	    var aiPhotoCleanupEnabled: Bool {
292	        didSet { UserDefaults.standard.set(aiPhotoCleanupEnabled, forKey: Keys.aiPhotoCleanup) }
293	    }
294	
295	    /// Per-provider selected cloud model IDs.
296	    private(set) var cloudModelSelections: [String: String] {
297	        didSet { persistDictionary(cloudModelSelections, key: Keys.cloudModels) }
298	    }
299	
300	    /// Per-provider base URL overrides (empty entry → use provider default).
301	    private(set) var cloudBaseURLOverrides: [String: String] {
302	        didSet { persistDictionary(cloudBaseURLOverrides, key: Keys.cloudBaseURLs) }
303	    }
304	
305	    /// Per-provider API-format overrides ("openai" / "anthropic"). When absent,
306	    /// the provider's built-in style is used. Lets users point a provider at an
307	    /// Anthropic-compatible gateway (e.g. a Kimi "coding" endpoint).
308	    private(set) var apiStyleOverrides: [String: String] {
309	        didSet { persistDictionary(apiStyleOverrides, key: Keys.cloudAPIStyles) }
310	    }
311	
312	    /// In-memory mirror of Keychain API keys so SwiftUI reacts to changes.
313	    /// Loaded from the Keychain at init; writes go through to the Keychain.
314	    private(set) var apiKeys: [String: String] = [:]
315	
316	    // MARK: - Initialization
317	
318	    private init() {
319	        let savedProvider = UserDefaults.standard.string(forKey: Keys.provider) ?? AIProvider.appleIntelligence.rawValue
320	        self.provider = AIProvider(rawValue: savedProvider) ?? .appleIntelligence
321	
322	        self.ollamaModel = UserDefaults.standard.string(forKey: Keys.ollamaModel) ?? "gpt-oss:20b"
323	        self.ollamaHost = UserDefaults.standard.string(forKey: Keys.ollamaHost) ?? "http://localhost:11434"
324	        self.enableThinking = UserDefaults.standard.object(forKey: Keys.enableThinking) as? Bool ?? true
325	        self.contextLength = UserDefaults.standard.object(forKey: Keys.contextLength) as? Int ?? 128000
326	        self.aiPhotoCleanupEnabled = UserDefaults.standard.object(forKey: Keys.aiPhotoCleanup) as? Bool ?? false
327	
328	        self.cloudModelSelections = AIModelSettings.loadDictionary(key: Keys.cloudModels)
329	        self.cloudBaseURLOverrides = AIModelSettings.loadDictionary(key: Keys.cloudBaseURLs)
330	        self.apiStyleOverrides = AIModelSettings.loadDictionary(key: Keys.cloudAPIStyles)
331	
332	        // Load API keys from Keychain into the observable mirror.
333	        var keys: [String: String] = [:]
334	        for p in AIProvider.allCases where p.isCloud {
335	            if let value = KeychainHelper.get(account: p.keychainAccount), !value.isEmpty {
336	                keys[p.rawValue] = value
337	            }
338	        }
339	        self.apiKeys = keys
340	
341	        updateOllamaServiceHost()
342	    }
343	
344	    // MARK: - Per-Provider Accessors
345	
346	    /// The API key for a cloud provider (empty string when none).
347	    func apiKey(for provider: AIProvider) -> String {
348	        apiKeys[provider.rawValue] ?? ""
349	    }
350	
351	    /// Store or clear a cloud provider's API key (Keychain + observable mirror).
352	    func setAPIKey(_ value: String, for provider: AIProvider) {
353	        let trimmed = value.trimmingCharacters(in: .whitespacesAndNewlines)
354	        KeychainHelper.set(trimmed, account: provider.keychainAccount)
355	        if trimmed.isEmpty {
356	            apiKeys.removeValue(forKey: provider.rawValue)
357	        } else {
358	            apiKeys[provider.rawValue] = trimmed
359	        }
360	    }
361	
362	    /// The effective base URL for a cloud provider (override or default).
363	    func baseURL(for provider: AIProvider) -> String {
364	        let override = cloudBaseURLOverrides[provider.rawValue]?.trimmingCharacters(in: .whitespacesAndNewlines)
365	        if let override, !override.isEmpty { return override }
366	        return provider.defaultBaseURL
367	    }
368	
369	    func setBaseURLOverride(_ value: String, for provider: AIProvider) {
370	        let trimmed = value.trimmingCharacters(in: .whitespacesAndNewlines)
371	        if trimmed.isEmpty || trimmed == provider.defaultBaseURL {
372	            cloudBaseURLOverrides.removeValue(forKey: provider.rawValue)
373	        } else {
374	            cloudBaseURLOverrides[provider.rawValue] = trimmed
375	        }
376	    }
377	
378	    /// The API-format override for a provider, or nil when using its default.
379	    func apiStyleOverride(for provider: AIProvider) -> AIProviderAPIStyle? {
380	        switch apiStyleOverrides[provider.rawValue] {
381	        case "anthropic": return .anthropic
382	        case "openai": return .openAICompatible
383	        default: return nil
384	        }
385	    }
386	
387	    func setAPIStyleOverride(_ style: AIProviderAPIStyle?, for provider: AIProvider) {
388	        switch style {
389	        case .anthropic: apiStyleOverrides[provider.rawValue] = "anthropic"
390	        case .openAICompatible: apiStyleOverrides[provider.rawValue] = "openai"
391	        case nil: apiStyleOverrides.removeValue(forKey: provider.rawValue)
392	        }
393	    }
394	
395	    /// The effective API style for a provider (override or built-in default).
396	    func effectiveAPIStyle(for provider: AIProvider) -> AIProviderAPIStyle {
397	        apiStyleOverride(for: provider) ?? provider.apiStyle
398	    }
399	
400	    /// Chat path derived from the effective API style.
401	    func effectiveChatPath(for provider: AIProvider) -> String {
402	        switch effectiveAPIStyle(for: provider) {
403	        case .anthropic: return "/v1/messages"
404	        case .openAICompatible: return provider == .minimax ? "/text/chatcompletion_v2" : "/chat/completions"
405	        }
406	    }
407	
408	    /// Models-list path derived from the effective API style.
409	    func effectiveModelsPath(for provider: AIProvider) -> String? {
410	        switch effectiveAPIStyle(for: provider) {
411	        case .anthropic: return "/v1/models"
412	        case .openAICompatible: return provider.modelsPath
413	        }
414	    }
415	
416	    /// Heuristic: does this model id look vision-capable (accepts images)?
417	    static func isLikelyVisionModel(_ id: String) -> Bool {
418	        let l = id.lowercased()
419	        if ["vl", "vision", "omni", "qvq", "4v", "glm-4.5v", "pixtral", "llava", "internvl", "minicpm-v", "gemini"]
420	            .contains(where: { l.contains($0) }) { return true }
421	        // Providers whose flagship chat models are multimodal.
422	        if l.hasPrefix("claude-") || l.contains("gpt-4o") || l.contains("gpt-4.1") || l.hasPrefix("o4") || l.hasPrefix("o3") { return true }
423	        // Doubao multimodal "seed"/vision families.
424	        if l.contains("seed-1-6") || l.contains("seed-1-8") || l.contains("seed-2-") || l.contains("1-5-vision") { return true }
425	        return false
426	    }
427	
428	    /// Resolve a vision-capable model for image tasks: the user's selected model
429	    /// if it's vision-capable, otherwise a vision model from the live list, then
430	    /// the provider's curated default vision model.
431	    func visionModel(for provider: AIProvider) -> String? {
432	        let selected = selectedModel(for: provider)
433	        // Respect the user's selection if it's already a vision model.
434	        if Self.isLikelyVisionModel(selected) { return selected }
435	        // Otherwise prefer the provider's known-good vision model.
436	        if let curated = provider.defaultVisionModel { return curated }
437	        // Last resort: any vision-looking model from the live list.
438	        return CloudAIService.shared.models(for: provider).map(\.id).first(where: Self.isLikelyVisionModel)
439	    }
440	
441	    /// The selected model for a provider. Ollama maps to `ollamaModel`;
442	    /// cloud providers use their per-provider selection (or first default).
443	    func selectedModel(for provider: AIProvider) -> String {
444	        switch provider {
445	        case .ollama:
446	            return ollamaModel
447	        case .appleIntelligence:
448	            return ""
449	        default:
450	            if let chosen = cloudModelSelections[provider.rawValue], !chosen.isEmpty {
451	                return chosen
452	            }
453	            return provider.defaultModels.first ?? ""
454	        }
455	    }
456	
457	    func setSelectedModel(_ model: String, for provider: AIProvider) {
458	        switch provider {
459	        case .ollama:
460	            ollamaModel = model
461	        case .appleIntelligence:
462	            break
463	        default:
464	            cloudModelSelections[provider.rawValue] = model
465	        }
466	    }
467	
468	    // MARK: - Availability
469	
470	    /// Whether Apple Intelligence is available.
471	    var isAppleIntelligenceAvailable: Bool {
472	        #if canImport(FoundationModels)
473	        return AIWordExplanationService.shared.isAvailable
474	        #else
475	        return false
476	        #endif
477	    }
478	
479	    /// Whether a given provider is usable right now.
480	    func isAvailable(_ provider: AIProvider) -> Bool {
481	        switch provider {
482	        case .appleIntelligence:
483	            return isAppleIntelligenceAvailable
484	        case .ollama:
485	            return OllamaService.shared.isConnected
486	        default:
487	            return !apiKey(for: provider).isEmpty
488	        }
489	    }
490	
491	    /// Whether any provider is available for AI features.
492	    var isAnyProviderAvailable: Bool {
493	        AIProvider.allCases.contains { isAvailable($0) }
494	    }
495	
496	    /// Current effective provider — the selected one if usable, otherwise the
497	    /// first available provider, otherwise the selected one (so errors surface).
498	    var effectiveProvider: AIProvider {
499	        if isAvailable(provider) { return provider }
500	        return AIProvider.allCases.first { isAvailable($0) } ?? provider
501	    }
502	
503	    /// Whether Ollama is selected and available.
504	    var isOllamaActive: Bool {
505	        provider == .ollama && OllamaService.shared.isConnected
506	    }
507	
508	    /// Status message for the current configuration.
509	    var statusMessage: String {
510	        switch provider {
511	        case .appleIntelligence:
512	            return isAppleIntelligenceAvailable
513	                ? "Apple Intelligence is ready"
514	                : (AIWordExplanationService.shared.unavailabilityReason ?? "Apple Intelligence is not available")
515	        case .ollama:
516	            if OllamaService.shared.isConnected {
517	                return ollamaModel.isEmpty ? "Connected — select a model" : "Connected to \(ollamaModel)"
518	            }
519	            return OllamaService.shared.connectionError ?? "Not connected to Ollama"
520	        default:
521	            if apiKey(for: provider).isEmpty {
522	                return "Add your \(provider.displayName) API key"
523	            }
524	            let model = selectedModel(for: provider)
525	            return model.isEmpty ? "Ready — select a model" : "Using \(model)"
526	        }
527	    }
528	
529	    /// Options dictionary for Ollama requests based on current settings.
530	    var ollamaOptions: [String: Ollama.Value] {
531	        [
532	            "num_ctx": .int(contextLength),
533	            "temperature": .double(0.7),
534	            "top_p": .double(0.9),
535	            "repeat_penalty": .double(1.1),
536	            "num_predict": .int(-1),
537	        ]
538	    }
539	
540	    // MARK: - Methods
541	
542	    private func updateOllamaServiceHost() {
543	        if let url = URL(string: ollamaHost) {
544	            OllamaService.shared.hostURL = url
545	        }
546	    }
547	
548	    /// Refresh connection and available models for the active provider.
549	    func refreshConnection() async {
550	        switch provider {
551	        case .ollama:
552	            await OllamaService.shared.checkConnection()
553	            if OllamaService.shared.isConnected {
554	                await OllamaService.shared.refreshModels()
555	            }
556	        default:
557	            if provider.isCloud {
558	                await CloudAIService.shared.refreshModels(for: provider)
559	            }
560	        }
561	    }
562	
563	    /// Select the first available Ollama model if none is selected.
564	    func selectDefaultModelIfNeeded() {
565	        if ollamaModel.isEmpty, let firstModel = OllamaService.shared.availableModels.first {
566	            ollamaModel = firstModel.name
567	        }
568	    }
569	
570	    /// Reset to default settings.
571	    func resetToDefaults() {
572	        provider = .appleIntelligence
573	        ollamaModel = "gpt-oss:20b"
574	        ollamaHost = "http://localhost:11434"
575	        enableThinking = true
576	        contextLength = 128000
577	        aiPhotoCleanupEnabled = false
578	    }
579	
580	    // MARK: - Persistence Helpers
581	
582	    private func persistDictionary(_ dict: [String: String], key: String) {
583	        if let data = try? JSONEncoder().encode(dict) {
584	            UserDefaults.standard.set(data, forKey: key)
585	        }
586	    }
587	
588	    private static func loadDictionary(key: String) -> [String: String] {
589	        guard let data = UserDefaults.standard.data(forKey: key),
590	              let dict = try? JSONDecoder().decode([String: String].self, from: data) else {
591	            return [:]
592	        }
593	        return dict
594	    }
595	}
