//
//  SavedTerm.swift
//  SwiftMandarin
//
//  Model for saved vocabulary terms
//

import Foundation
import SwiftUI
import Observation

struct SavedTerm: Identifiable, Codable, Equatable, Hashable {
    let id: UUID
    let chinese: String
    let pinyin: String
    let definition: String
    let partOfSpeech: String
    let dateAdded: Date
    var sortOrder: Int
    var isMastered: Bool

    init(
        id: UUID = UUID(),
        chinese: String,
        pinyin: String,
        definition: String,
        partOfSpeech: String = "",
        dateAdded: Date = Date(),
        sortOrder: Int = 0,
        isMastered: Bool = false
    ) {
        self.id = id
        self.chinese = chinese
        self.pinyin = pinyin
        self.definition = definition
        self.partOfSpeech = partOfSpeech
        self.dateAdded = dateAdded
        self.sortOrder = sortOrder
        self.isMastered = isMastered
    }
}

// MARK: - Saved Terms Store

@Observable
@MainActor
final class SavedTermsStore {
    static let shared = SavedTermsStore()

    var terms: [SavedTerm] = [] {
        didSet { save() }
    }

    /// Public accessor for saved terms (alias for terms)
    var savedTerms: [SavedTerm] { terms }

    private let saveKey = "savedTerms"

    private init() {
        load()
    }

    // MARK: - Public Methods

    func add(_ term: SavedTerm) {
        guard !terms.contains(where: { $0.chinese == term.chinese }) else { return }
        var newTerm = term
        newTerm.sortOrder = terms.count
        terms.append(newTerm)
        // Track activity with part of speech
        LearningActivityStore.shared.recordWordLearned(partOfSpeech: term.partOfSpeech)
    }

    func add(chinese: String, pinyin: String, definition: String, partOfSpeech: String = "") {
        guard !terms.contains(where: { $0.chinese == chinese }) else { return }

        let newTerm = SavedTerm(
            chinese: chinese,
            pinyin: pinyin,
            definition: definition,
            partOfSpeech: partOfSpeech,
            sortOrder: terms.count
        )
        terms.append(newTerm)
        // Track activity with part of speech
        LearningActivityStore.shared.recordWordLearned(partOfSpeech: partOfSpeech)
    }

    func remove(at offsets: IndexSet) {
        terms.remove(atOffsets: offsets)
        updateSortOrders()
    }

    func remove(_ term: SavedTerm) {
        terms.removeAll { $0.id == term.id }
        updateSortOrders()
    }

    func remove(chinese: String) {
        terms.removeAll { $0.chinese == chinese }
        updateSortOrders()
    }

    func term(withID id: UUID) -> SavedTerm? {
        terms.first { $0.id == id }
    }

    func update(_ updatedTerm: SavedTerm) {
        guard let index = terms.firstIndex(where: { $0.id == updatedTerm.id }) else { return }

        var replacement = updatedTerm
        replacement.sortOrder = terms[index].sortOrder
        terms[index] = replacement
    }

    func move(from source: Int, to destination: Int) {
        terms.move(fromOffsets: IndexSet(integer: source), toOffset: destination)
        updateSortOrders()
    }

    func contains(chinese: String) -> Bool {
        terms.contains { $0.chinese == chinese }
    }

    func clear() {
        terms.removeAll()
    }

    /// Toggle the mastered status of a term
    func toggleMastered(_ term: SavedTerm) {
        guard let index = terms.firstIndex(where: { $0.id == term.id }) else { return }
        terms[index].isMastered.toggle()
    }

    /// Set the mastered status of a term
    func setMastered(_ term: SavedTerm, isMastered: Bool) {
        guard let index = terms.firstIndex(where: { $0.id == term.id }) else { return }
        terms[index].isMastered = isMastered
    }

    /// Count of mastered terms
    var masteredCount: Int {
        terms.filter { $0.isMastered }.count
    }

    // MARK: - Private Methods

    private func updateSortOrders() {
        for (index, _) in terms.enumerated() {
            terms[index].sortOrder = index
        }
    }

    private func save() {
        if let encoded = try? JSONEncoder().encode(terms) {
            UserDefaults.standard.set(encoded, forKey: saveKey)
        }
    }

    private func load() {
        if let data = UserDefaults.standard.data(forKey: saveKey),
           let decoded = try? JSONDecoder().decode([SavedTerm].self, from: data) {
            terms = decoded.sorted { $0.sortOrder < $1.sortOrder }
        }
    }
}

//
//  LearningCard.swift
//  SwiftMandarin
//
//  Flashcard model for learning with spaced repetition
//

import Foundation
import SwiftUI
import Observation

struct LearningCard: Identifiable, Hashable, Codable {
    let id: String
    let chinese: String
    let english: String
    let pinyin: String?
    let exampleSentence: String?
    let tags: [String]
    let notes: String?

    init(chinese: String, english: String, pinyin: String? = nil, exampleSentence: String? = nil, tags: [String] = [], notes: String? = nil) {
        self.id = chinese
        self.chinese = chinese
        self.english = english
        self.pinyin = pinyin
        self.exampleSentence = exampleSentence
        self.tags = tags
        self.notes = notes
    }
}

// MARK: - Card Progress (Spaced Repetition)

struct CardProgress: Codable, Identifiable {
    let cardId: String
    var masteryLevel: MasteryLevel
    var reviewCount: Int
    var correctCount: Int
    var lastReviewDate: Date?
    var nextReviewDate: Date
    var easeFactor: Double

    var id: String { cardId }

    var accuracy: Double {
        guard reviewCount > 0 else { return 0 }
        return Double(correctCount) / Double(reviewCount)
    }

    init(cardId: String) {
        self.cardId = cardId
        self.masteryLevel = .new
        self.reviewCount = 0
        self.correctCount = 0
        self.lastReviewDate = nil
        self.nextReviewDate = Date()
        self.easeFactor = 2.5
    }

    mutating func recordReview(correct: Bool, quality: ReviewQuality) {
        let reviewDate = Date()
        let priorReviewDate = lastReviewDate
        let previousInterval = max(
            nextReviewDate.timeIntervalSince(priorReviewDate ?? reviewDate),
            60 * 60 * 24
        )

        reviewCount += 1
        if correct { correctCount += 1 }
        lastReviewDate = reviewDate
        updateMasteryLevel()
        calculateNextReview(
            quality: quality,
            reviewDate: reviewDate,
            previousInterval: previousInterval
        )
    }

    private mutating func updateMasteryLevel() {
        switch accuracy {
        case 0..<0.3: masteryLevel = .learning
        case 0.3..<0.5: masteryLevel = .learning
        case 0.5..<0.7: masteryLevel = .familiar
        case 0.7..<0.9: masteryLevel = .proficient
        default: masteryLevel = reviewCount >= 5 ? .mastered : .proficient
        }
    }

    private mutating func calculateNextReview(
        quality: ReviewQuality,
        reviewDate: Date,
        previousInterval: TimeInterval
    ) {
        let q = Double(quality.rawValue)
        easeFactor = max(1.3, easeFactor + 0.1 - (5.0 - q) * (0.08 + (5.0 - q) * 0.02))

        let interval: TimeInterval
        if quality.rawValue < 3 {
            interval = 60 * 10 // 10 minutes
        } else {
            switch reviewCount {
            case 1: interval = 60 * 60 * 24 // 1 day
            case 2: interval = 60 * 60 * 24 * 6 // 6 days
            default:
                interval = previousInterval * easeFactor
            }
        }
        nextReviewDate = reviewDate.addingTimeInterval(interval)
    }
}

enum MasteryLevel: String, Codable, CaseIterable {
    case new, learning, familiar, proficient, mastered

    var label: String {
        rawValue.capitalized
    }
}

enum ReviewQuality: Int, CaseIterable {
    case blackout = 0
    case incorrect = 1
    case difficult = 2
    case hard = 3
    case good = 4
    case easy = 5
}

// MARK: - Learning Deck (Built-in Cards)

enum LearningDeck {
    static let cards: [LearningCard] = [
        LearningCard(chinese: "你好", english: "Hello", exampleSentence: "你好，我是小明。", tags: ["Greeting"]),
        LearningCard(chinese: "谢谢", english: "Thank you", exampleSentence: "谢谢你的帮助。", tags: ["Polite"]),
