816	    /// Clean English text for processing - removes line breaks that split sentences
817	    private func cleanTextForProcessing(_ text: String) -> String {
818	        var result = text
819	        
820	        // Replace multiple whitespace/newlines with single space
821	        result = result.components(separatedBy: .whitespacesAndNewlines)
