            Image(systemName: "xmark.circle.fill")
                .foregroundStyle(.tertiary)
        }
        .buttonStyle(.plain)
        .accessibilityLabel(Text("Dismiss"))
    }
    .padding(10)
    .background(RoundedRectangle(cornerRadius: 10).fill(Color.orange.opacity(0.1)))
}

