        await MainActor.run { sourceText = textToProcess }
        await processText(textToProcess, knownLanguage: languageHint)
    } catch {
        guard !Task.isCancelled else { return }
        await MainActor.run {
            errorMessage = error.localizedDescription
            isProcessing = false
        }
    }
}

