export const meta = {
  name: 'review-overhaul-diff',
  description: 'Adversarially review the uncommitted overhaul diff for bugs and regressions',
  phases: [
    { title: 'Review', detail: 'parallel reviewers by dimension' },
    { title: 'Verify', detail: 'adversarial verification of findings' },
  ],
}

const ROOT = '/Users/rogerlin/XCode-Projects/SwiftMandarinShortcuts'
const CONTEXT = `
Repo: ${ROOT} (SwiftMandarin — multiplatform SwiftUI app, iOS/macOS 26.2, Swift 5 mode).
An overhaul session produced UNCOMMITTED changes (run \`git -C ${ROOT} diff\` and \`git -C ${ROOT} status --short\` to see them; new untracked file: SwiftMandarin/Models/PersistentCodableStore.swift, README.zh-Hans.md).
Key intentional changes (do NOT report these as issues):
- pbxproj surgery: emptied duplicate Sources phase (synchronized file group supplies sources), removed legacy refs, added exception set excluding 'logs' and 'MandarinKit.md', filled mic/speech usage descriptions. Both platforms verified BUILD SUCCEEDED with zero warnings AFTER all changes.
- Item.swift deleted; SwiftMandarin/logs removed (session logs, gitignored now).
- Stores now load/save via PersistentCodableStore (backup/restore + os.log).
- cleanupRecognizedText now returns String? (nil = no provider); PhotoTranslateView shows banner/badge + revert.
- gradeWorkbook throws on empty-question results instead of returning 0/0.
- stopRecording() made idempotent and called from error paths.
- TextRecognitionResult honors explicit scan language.
- PinyinConverter returns "" for non-CJK input.
- Live speech onUseTranslation now passes (transcript, translation); TranslateView sets both + records history.
- Photo translations write TranslationHistoryStore (gated on saveToHistoryAutomatically).
- RubyTextView honors showPinyin/pinyinPosition/toneColors; MoreView gained Pinyin Position picker.
- HistoryTabView: direction filter + clear-all confirmation + no-matches state.
- AIProviderConfigView: Test Connection + capability badges.
- TranslationDirection source/targetLanguageName now String(localized:); EnglishTextAnalyzer grammar points localized; grading errors localized.
- Localizable.xcstrings: +47 keys (zh-Hans translated), re-sorted by python (cosmetic ordering churn is known/accepted).
- READMEs updated (EN) / added (zh-Hans).`

const FINDINGS_SCHEMA = {
  type: 'object',
  properties: {
    findings: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          title: { type: 'string' },
          file: { type: 'string' },
          line: { type: 'number' },
          severity: { type: 'string', enum: ['critical', 'high', 'medium', 'low'] },
          evidence: { type: 'string', description: 'quote the diff hunk or code proving the issue' },
          fix: { type: 'string' },
        },
        required: ['title', 'file', 'severity', 'evidence', 'fix'],
      },
    },
  },
  required: ['findings'],
}

const VERDICT_SCHEMA = {
  type: 'object',
  properties: {
    isReal: { type: 'boolean' },
    reasoning: { type: 'string' },
    fixApproach: { type: 'string' },
  },
  required: ['isReal', 'reasoning', 'fixApproach'],
}

const DIMENSIONS = [
  { key: 'correctness', prompt: 'Logic/correctness bugs introduced BY THE DIFF: inverted conditions, broken control flow, wrong optionality handling (esp. cleanupRecognizedText String? change and all its call sites), state not reset, regressions vs the old behavior the diff replaced. Read the full diff hunk-by-hunk and trace each change against its surrounding file.' },
  { key: 'concurrency', prompt: 'Concurrency issues introduced BY THE DIFF: the SpeechRecognitionService error-path teardown (re-entrancy, calling stopRecording from inside recognitionTask, Task.isCancelled semantics inside the catch — note Task.isCancelled there refers to the recognitionTask itself), PhotoTranslateView task cancel-before-replace + isProcessing flag consistency when superseded tasks return early, MainActor.run usage.' },
  { key: 'data-persistence', prompt: 'Data-integrity issues in the PersistentCodableStore changes: backup promote/restore logic, key collisions, what happens on first launch, whether SavedTermsStore.terms didSet save() ordering still works with load() (didSet during init?), LearningActivity keyFormatter thread-safety (static DateFormatter accessed from where?), dedup normalizedKey behavior on legitimate distinct terms.' },
  { key: 'localization-ui', prompt: 'Localization/UI issues in the diff: new LocalizedStringKey usages that will NOT resolve (String vs LocalizedStringKey mixups), the Localizable.xcstrings edits (validate JSON parses, spot-check 10 new entries for placeholder fidelity and translation quality), Picker tag types matching selection types (HistoryTabView TranslationDirection? tags, MoreView pinyinPosition strings), README.zh-Hans.md accuracy vs README.md (spot-check sections).' },
]

phase('Review')
const reviews = await parallel(DIMENSIONS.map(d => () =>
  agent(`You are reviewing UNCOMMITTED changes in ${ROOT}. ${CONTEXT}\n\nYour dimension: ${d.prompt}\n\nUse \`git -C ${ROOT} diff\` (and Read files for full context around hunks). Report at most 8 findings with quoted evidence. Only report issues INTRODUCED or MISSED by this diff that have real user-visible or correctness consequences. No style nits, no re-litigating intentional changes listed above.`,
    { label: `review:${d.key}`, phase: 'Review', schema: FINDINGS_SCHEMA, agentType: 'Explore' })))

const all = reviews.filter(Boolean).flatMap(r => r.findings)
const seen = new Map()
for (const f of all) {
  const k = (f.file || '') + '|' + (f.title || '').toLowerCase().replace(/[^a-z0-9]/g, '').slice(0, 32)
  if (!seen.has(k)) seen.set(k, f)
}
const unique = Array.from(seen.values())
log(`${all.length} findings → ${unique.length} unique`)

phase('Verify')
const verified = await parallel(unique.map(f => () =>
  agent(`Adversarial verifier for ${ROOT}. ${CONTEXT}\n\nA reviewer claims:\nTITLE: ${f.title}\nFILE: ${f.file}${f.line ? ':' + f.line : ''}\nSEVERITY: ${f.severity}\nEVIDENCE: ${f.evidence}\nFIX: ${f.fix}\n\nTry to REFUTE it by reading the actual current files (working tree, not HEAD). isReal=true ONLY if the consequence genuinely occurs in the current working-tree code. Note both platforms already compile cleanly — compile-error claims are false by definition.`,
    { label: `verify:${(f.title || '').slice(0, 36)}`, phase: 'Verify', schema: VERDICT_SCHEMA, agentType: 'Explore' })
    .then(v => ({ ...f, verdict: v }))))

const confirmed = verified.filter(Boolean).filter(x => x.verdict && x.verdict.isReal)
return {
  confirmed: confirmed.map(c => ({ title: c.title, file: c.file, line: c.line, severity: c.severity, evidence: c.evidence, fix: c.verdict.fixApproach })),
  refuted: verified.filter(Boolean).length - confirmed.length,
}

